// Kategoria z odpowiedzi modelu; błąd Ollamy => NIEZNANE (mail i tak trafi do powiadomienia)
const g = $('Gmail – macmalonet783').item.json;
const odp = String(($json.message && $json.message.content) || '').replace(/<think>[\s\S]*?<\/think>/gi, '').toUpperCase();
const kategoria = ['SPAM', 'NEWSLETTER', 'BIZNES', 'OSOBISTE'].find(k => odp.includes(k)) || 'NIEZNANE';
return { json: {
  kategoria,
  messageId: g.id,
  temat: g.Subject || g.subject || '(bez tematu)',
  od: g.From || g.from || '',
  konto: 'macmalonet783',
} };

// Nazwy etykiet w Gmailu (wielkość liter bez znaczenia). Utwórz brakujące w Gmailu.
const NAZWY = { BIZNES: 'BIZNES', OSOBISTE: 'OSOBISTE', NEWSLETTER: 'NEWSLETTER', SPAM: 'AI/Spam?' };
const mapa = {};
for (const l of $input.all()) if (l.json && l.json.name) mapa[l.json.name.toLowerCase()] = l.json.id;
return $('Klasyfikacja – macmalonet783').all().map(i => {
  const nazwa = NAZWY[i.json.kategoria];
  const labelId = nazwa ? (mapa[nazwa.toLowerCase()] || null) : null;
  return { json: { ...i.json, labelId, brakEtykiety: nazwa && !labelId ? nazwa : null } };
});

// Powiadomienie tylko dla BIZNES / OSOBISTE / NIEZNANE (NIEZNANE = Ollama nie odpowiedziała)
const USER_ID = '340572098873393153';
const KOLOR = { BIZNES: 15844367, OSOBISTE: 3066993, NIEZNANE: 9807270 };
const wazne = $input.all().map(i => i.json).filter(m => KOLOR[m.kategoria]);
return wazne.map(m => ({ json: {
  content: `<@${USER_ID}> 📧 nowy ważny mail`,
  embeds: [{
    title: `${m.kategoria} — ${m.temat}`.slice(0, 250),
    description: `**Od:** ${m.od}`.slice(0, 1000),
    color: KOLOR[m.kategoria],
    footer: { text: `JARVIS • ${m.konto}${m.brakEtykiety ? ' • brak etykiety ' + m.brakEtykiety + ' w Gmailu' : ''}` },
    timestamp: new Date().toISOString(),
  }],
  allowed_mentions: { users: [USER_ID] },
} }));

